  @Test
  public void testGenericCheck_MysqlAndPostgresDatabaseInjection() {
    // The mysql:// family uses '?' / '&' for query params and '#' as the fragment anchor.
    Map<String, Object> params = new HashMap<>();
    params.put("k1", "v1");
    Assertions.assertThrows(
